import re, os, ezdxf

base = '/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind'

with open(os.path.join(base, 'project/20_survey/NDDC-A2_Federated_Model_2026.ifc')) as f:
    ifc_lines = [l.strip() for l in f if l.strip()]

# Let's see all IFCWALL, IFCOPENINGELEMENT, IFCSLAB, and their properties
entities = {}
for l in ifc_lines:
    m = re.match(r'^(#\d+)=(.*);$', l)
    if m:
        entities[m.group(1)] = m.group(2)

# Find all IFCROPERTYSINGLEVALUE and IFCPROPERTYSET and IFCRELDEFINESBYPROPERTIES
for k, v in entities.items():
    if v.startswith('IFCWALL(') or v.startswith('IFCOPENINGELEMENT(') or v.startswith('IFCSLAB(') or v.startswith('IFCPROPERTYSET('):
        print(k, v)
"

python3 -c "
import re, os

base = '/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind'
with open(os.path.join(base, 'project/20_survey/NDDC-A2_Federated_Model_2026.ifc')) as f:
    ifc_lines = [l.strip() for l in f if l.strip()]

entities = {}
for l in ifc_lines:
    m = re.match(r'^(#\d+)=(.*);$', l)
    if m:
        entities[m.group(1)] = m.group(2)

print('Max entity id:', list(entities.keys())[-10:])
for k, v in entities.items():
    if v.startswith('IFCRELDEFINESBYPROPERTIES('):
        # parse related object and property set
        m = re.search(r'\((#\d+)\),(#\d+)\)$', v)
        if m:
            obj_id, pset_id = m.group(1), m.group(2)
            obj = entities[obj_id]
            pset = entities[pset_id]
            props_str = re.search(r'\((#\d+(?:,#\d+)*)\)\)$', pset).group(1)
            prop_ids = props_str.split(',')
            props = {}
            for pid in prop_ids:
                pv = entities[pid]
                # IFCPROPERTYSINGLEVALUE('Name',$,TYPE(val),$)
                pm = re.match(r\"IFCPROPERTYSINGLEVALUE\('([^']+)',\$,[A-Z]+\(([^)]+)\),\$\)\", pv)
                if pm:
                    props[pm.group(1)] = pm.group(2).strip(\"'\")
                else:
                    props[pid] = pv
            print(obj_id, obj.split(',')[2], props)
"

